def transform(A, B):
    if len(A) != len(B):
        return -1

    # Check if B is a rotation of A
    if B in (A + A):
        count = 0
        j = 0
        for i in range(len(A)):
            if A[i] == B[j]:
                j += 1
            else:
                count += 1
        return count
    else:
        return -1

